import fs from 'node:fs/promises';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

// Export sizes and formats only. Artwork is generated by the built-in image_gen tool.
const require = process.argv[2]
  ? createRequire(path.resolve(process.argv[2], 'package.json'))
  : createRequire(import.meta.url);
const sharp = require('sharp');
const root = fileURLToPath(new URL('../', import.meta.url));
const sources = path.join(root, 'design', 'brand-ai');
const output = path.join(root, 'public', 'brand');
const logo = await fs.readFile(path.join(sources, 'logo-original.png'));
const icon = await fs.readFile(path.join(sources, 'icon-original.png'));
const og = await fs.readFile(path.join(sources, 'og-original.png'));

await sharp(logo).resize(512, 512, { fit: 'contain', background: '#00000000' }).png()
  .toFile(path.join(output, 'logo-ai.png'));
await sharp(logo).resize(160, 160, { fit: 'contain', background: '#00000000' }).webp({ quality: 90, alphaQuality: 100 })
  .toFile(path.join(output, 'logo-ai-header.webp'));
await Promise.all([32, 192, 512].map(size => sharp(icon).resize(size, size).png()
  .toFile(path.join(output, `icon-ai-${size}.png`))));
await sharp(icon).resize(180, 180).png().toFile(path.join(output, 'apple-touch-icon-ai.png'));
await sharp(og).resize(1200, 630, { fit: 'cover', position: 'centre' }).jpeg({ quality: 92, mozjpeg: true })
  .toFile(path.join(output, 'og-ai.jpg'));

const sizes = [16, 32, 48, 64];
const images = await Promise.all(sizes.map(size => sharp(icon).resize(size, size).png().toBuffer()));
const header = Buffer.alloc(6 + sizes.length * 16);
header.writeUInt16LE(1, 2);
header.writeUInt16LE(sizes.length, 4);
let offset = header.length;
images.forEach((image, i) => {
  const entry = 6 + i * 16;
  header[entry] = sizes[i];
  header[entry + 1] = sizes[i];
  header.writeUInt16LE(1, entry + 4);
  header.writeUInt16LE(32, entry + 6);
  header.writeUInt32LE(image.length, entry + 8);
  header.writeUInt32LE(offset, entry + 12);
  offset += image.length;
});
const ico = Buffer.concat([header, ...images]);
await fs.writeFile(path.join(output, 'favicon-ai.ico'), ico);
await fs.writeFile(path.join(root, 'public', 'favicon.ico'), ico);
console.log('Exported AI logo, icons, and 1200 × 630 social preview.');
